@spec patternEditor_shelf_spec  src=tests/specs/patternEditor_shelf_spec.lua  loc=287  sha=4602222  cases=7
@exercises patternEditor (pe), dataStore (h.ds)
@surface   pe:open, pe:draw, pe:handleInput, ds:get, ds:assign
@harness   mk, reaper.GetMediaItemTake_Track

# Intent
  design/fx-patterns.md P4: the library copy shelf -- Save/Load in the pattern-editor toolbar.
  Save and Load are both chrome.drawPicker widgets, captured by kind through a fake chrome; gridPane
  is swapped for an inert stub via util._stubs so pe:draw's toolbar runs without the grid render.

# Helpers
  @fn keyId(name)  @ 11-20
  @fn setKeys(keys, mods)  @ 54-57
  @fn loadPE(deps)  @ 74-83
  @fn notesBody()  @ 85-93
  @fn curveBody()  @ 95-100
  @fn withEditor(harness, body, poly)  @ 104-111
      -- Open the editor on `body`, capturing each write-through commit; get() reads the latest. hostDs is
      -- the harness ds (project scope), standing in for trackerPage's shared ds.
  @fn frame(pe, o)  @ 114-119
      -- One draw frame: queue a button press / injected input text / held keys, then draw.
  @fn input(pe, keys)  @ 121-124

# Cases
  @case 'Save stores a whitelisted copy on the host ds under a typed new name'  [harness]  @ 128-140
  @case 'Save over an existing name overwrites immediately, no confirm'  [harness]  @ 144-159
  @case 'Load rematerialises the picked body; the param tracks it'  [harness]  @ 163-179
  @case 'both pickers offer only matching kind, and matching domain for curves'  [harness]  @ 183-213
  @case 'Esc after a Load restores the modal-open snapshot, not the loaded body'  [harness]  @ 217-232
  @case 'a mono note param offers only single-lane bodies; a poly param offers multi-lane too'  [harness]  @ 236-264
  @case 'Load offers a per-row delete that drops just that name; Save offers none'  [harness]  @ 268-285

